def main():
    output=ROOT/'all225_clean_meanings_before_English.json';assert not output.exists()
    packet,styles,menus,scope=map(load,(ELIGIBLE,ROOT/'clean_style_objects.json',ROOT/'clean_choice_objects.json',SCOPE))
    rows=[]
    for group in packet['groups']:
        expected=MEANINGS.get(group['block'],{})
        assert set(expected)=={r['source_reference']['record_index'] for r in group['records']}
        for original in group['records']:
            row=deepcopy(original);index=row['source_reference']['record_index']
            row.update(source_meaning=expected[index],exchange_context=CONTEXT[row['block']],source_only_not_final_English=True)
            rows.append(row)
    assert len(rows)==209
    registers={0:'Conversational, ordinarily polite.',1:'Formal and deferential, with a formal term for letter.',
        2:'Conversational and lightly casual.',3:'Gentle and polite; do not invent an intimate relationship.',
        4:'Rougher familiar delivery.',5:'Older-speaker declarative diction.',6:'Informal childlike call; do not force baby talk.',7:'Expansive polite register sharing the original physical text with slot 2.'}
    for original in styles['records']:
        row=deepcopy(original);author='Charles' if row['block']==238 else 'Jam'
        row.update(source_meaning=f'The selected companion tells the admiral that a letter from {author} has arrived.',
            exchange_context=CONTEXT[row['block']],personality_voice_notes=[dict(source_index=i,register=registers[i]) for i in row['source_style_indices']],
            source_only_not_final_English=True)
        rows.append(row)
    for original in menus['records']:
        row=deepcopy(original)
        row.update(source_meaning=['Choose to attempt taking the figurehead.','Choose to leave the figurehead alone.'][row['source_index']],
            exchange_context=CONTEXT[243],source_only_not_final_English=True)
        rows.append(row)
    assert len(rows)==len({r['id'] for r in rows})==225 and scope['total_editorial_objects']==225
    save(output,dict(records=rows,records_count=225,ordinary_speeches=209,physical_personality_alternatives=14,typed_captions=2,
        complete_exchange_contexts=CONTEXT,source_meanings=225,remaining_meanings=0,
        English_drafts=0,current_story_English_compared=0,source_first_not_new_editorial_completion_credit=True,
        source_names_are_clean_metadata_not_native_consumer_orfinal_localization_approval=True,
        item_stat_andproper_name_final_forms_require_scoped_approved_term_binding=True,
        excluded_B237_already_credited=18,no_current_English_dialogue_consulted_for_eligible_records=True,
        all_five_review_gates_pending=True,new_credit=0,guide_photos=False,full_goal_complete=False,
        evidence={str(p):digest(p) for p in (ELIGIBLE,SCOPE,ROOT/'clean_style_objects.json',ROOT/'clean_choice_objects.json',ROOT/'clean_name_fields.json',Path(__file__))}))
    print('Sealed all 225 individual clean-source meanings and whole-exchange contexts; current story English remains unconsulted.')

if __name__=='__main__':main()
